import { type Claim, isOpen } from '../claims/claims';
import { type Late, type Rate, claimDue, dueTotal } from '../rates/rates';
import type { Settings } from '../settings/settings';
import type { Grades } from '../people/people';

/** The claim's due-by (yyyy-MM-dd): fixed when it was added, from the terms of its person's grade then. */
export const dueBy = (claim: Claim): string => claim.dueBy;

/** Whether the claim is overdue: it is OPEN (or PENDING) and its due-by is before the sheet's today. */
export function overdue(claim: Claim, today: string | undefined): boolean {
  return isOpen(claim) && today !== undefined && dueBy(claim) < today;
}

const DAY = 24 * 60 * 60 * 1000;

/** How many full 30 days the claim is overdue on the sheet's today (0 when it is not overdue). */
export function latePeriods(claim: Claim, today: string | undefined): number {
  if (today === undefined || !overdue(claim, today)) return 0;
  const days = (Date.parse(`${today}T00:00:00Z`) - Date.parse(`${dueBy(claim)}T00:00:00Z`)) / DAY;
  return Math.floor(days / 30);
}

/** What the sheet's late charge follows: its late percent, each claim's due-by and its today; and how it rounds:
 *  a claim rounding by a date before the policy date (else the sheet's today) rounds half up. */
export function lateOf(settings: Settings | undefined, today: string | undefined): Late {
  const policy = settings?.policyDate ?? today;
  return {
    pct: settings?.latePct,
    periods: (c) => latePeriods(c, today),
    halfUp: (c) => policy !== undefined && (c.roundsBy ?? c.date) < policy,
  };
}

/** A person's overdue claims among these (their claims that count): how many, and the sum of their
 *  dues (late charge included) at the person's grade in force on each claim's date, skipping n/a. */
export function overdueFigures(
  claims: Claim[],
  rates: Rate[] | undefined,
  grades: Grades,
  floor: string | undefined,
  today: string | undefined,
  lateCharge?: Late,
): { count: number; total: string } {
  const late = claims.filter((c) => overdue(c, today));
  return { count: late.length, total: dueTotal(late.map((c) => claimDue(c, rates, grades, floor, lateCharge))) };
}
import { HomeMain } from '../../slots/defs/homeMain';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { type Person, usePeople } from '../people/people';
import { useCurrentSheet } from '../../session/session';
import { useSheetToday } from '../sheet/sheet';
import { counts, live, useClaims } from '../claims/claims';
import { useSettings } from '../settings/settings';
import { dueTotal, useRates } from '../rates/rates';
import { lateOf, overdueFigures } from './overdue';

// A person's overdue count and overdue-total (the due of their overdue claims that count), and the sheet's.
function OverdueHead() {
  return (
    <>
      <th>Overdue</th>
      <th>Overdue total</th>
    </>
  );
}

function useOverdue() {
  const [sheet] = useCurrentSheet();
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const settings = useSettings(sheet).data;
  return (person: Person) =>
    overdueFigures(
      live((claims.data ?? []).filter((c) => c.personId === person.id), [person]).filter(counts),
      rates.data,
      person.grades,
      settings?.floor,
      today,
      lateOf(settings, today),
    );
}

function PersonOverdue({ person }: { person: Person }) {
  const { count, total } = useOverdue()(person);
  return (
    <>
      <td data-testid="person-overdue-count">{count}</td>
      <td data-testid="person-overdue-total">{total}</td>
    </>
  );
}

/** The sheet's overdue figures: everyone's overdue counts and overdue-totals added up. */
export function useSheetOverdue(): { count: number; total: string } {
  const [sheet] = useCurrentSheet();
  const people = usePeople(sheet);
  const figures = (people.data ?? []).map(useOverdue());
  return { count: figures.reduce((n, f) => n + f.count, 0), total: dueTotal(figures.map((f) => f.total)) };
}

function OverdueTotal() {
  const { count, total } = useSheetOverdue();
  return (
    <p>
      Overdue <strong data-testid="rollup-overdue-count">{count}</strong>{' '}
      Overdue total <strong data-testid="rollup-overdue-total">{total}</strong>
    </p>
  );
}

export const contributions = [
  PersonColumnHeads.fill({ order: 17, Component: OverdueHead }),
  PersonColumns.fill({ order: 17, Component: PersonOverdue }),
  HomeMain.fill({ order: 36, Component: OverdueTotal }),
];
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.SheetStore;

/** What a sheet's late charge follows: each claim's due-by (fixed when it was added), the sheet's late
 *  percent and its today. An overdue claim (OPEN or PENDING, due-by before today) gains the late percent of its
 *  figure for every full 30 days it is overdue, rounded as the sheet's {@link Rounding} has the claim. The charge is never bound by a
 *  statement; settling freezes it into the settled due. */
public record Lateness(BigDecimal pct, LocalDate today, Rounding rounding) {

    /** The days in each step of the late charge. */
    private static final int PERIOD_DAYS = 30;

    public static Lateness of(String sheetId, SettingStore settings, SheetStore sheets, ClaimStore claims) {
        return new Lateness(settings.latePct(sheetId), sheets.today(sheetId),
                Rounding.of(sheetId, settings, sheets, claims));
    }

    /** The late charge on a claim whose figure (bound, else floored live) is {@code figure}; none on
     *  a correction. */
    public BigDecimal charge(Claim claim, BigDecimal figure) {
        if (figure == null || !claim.getStatus().isOpen() || today == null || claim.isCorrection()) {
            return BigDecimal.ZERO.setScale(2);
        }
        long overdue = ChronoUnit.DAYS.between(claim.getDueBy(), today);
        long periods = overdue <= 0 ? 0 : overdue / PERIOD_DAYS;
        return ClaimFigure.of(figure, pct.multiply(BigDecimal.valueOf(periods)), rounding.mode(claim));
    }

    /** The claim's due now: its figure, plus the late charge unless settled (its settled due has it). */
    public BigDecimal due(Claim claim, BigDecimal pct, BigDecimal floor) {
        BigDecimal figure = ClaimFigure.of(claim, pct, floor, rounding);
        if (figure == null || claim.getSettledDue() != null) {
            return figure;
        }
        return figure.add(charge(claim, figure));
    }
}

